const { fonte, janela } = $json;
const versaoApi = 'v2';
const canal = String(fonte.externalId).trim();
const base = `https://youtubeanalytics.googleapis.com/${versaoApi}/reports`;
const MAXIMO_DE_DIAS_POR_RECORTE = 31;
const MAXIMO_DE_VIDEOS = 25;

const consulta = (parametros) => `${base}?${Object.entries({ ids: `channel==${canal}`, ...parametros })
  .map(([chave, valor]) => `${chave}=${encodeURIComponent(valor)}`).join('&')}`;
const periodo = { startDate: janela.start, endDate: janela.end };
const metricasDeAudiencia = 'views,estimatedMinutesWatched';

const dias = [];
const inicioDaJanela = new Date(`${janela.start}T00:00:00Z`).getTime();
for (let instante = new Date(`${janela.end}T00:00:00Z`).getTime(); instante >= inicioDaJanela && dias.length < MAXIMO_DE_DIAS_POR_RECORTE; instante -= 86400000) {
  dias.push(new Date(instante).toISOString().slice(0, 10));
}

const requisicoes = [
  { rotulo: 'canal_dia', url: consulta({ ...periodo, metrics: 'views,estimatedMinutesWatched,subscribersGained,subscribersLost', dimensions: 'day', sort: 'day' }) },
  { rotulo: 'receita', url: consulta({ ...periodo, metrics: 'estimatedRevenue', dimensions: 'day', sort: 'day' }) },
  { rotulo: 'origem_trafego', url: consulta({ ...periodo, metrics: metricasDeAudiencia, dimensions: 'day,insightTrafficSourceType', sort: 'day' }) },
  { rotulo: 'dispositivo', url: consulta({ ...periodo, metrics: metricasDeAudiencia, dimensions: 'day,deviceType', sort: 'day' }) },
  { rotulo: 'local_reproducao', url: consulta({ ...periodo, metrics: metricasDeAudiencia, dimensions: 'day,insightPlaybackLocationType', sort: 'day' }) },
  { rotulo: 'top_videos', url: consulta({ ...periodo, metrics: 'views', dimensions: 'video', sort: '-views', maxResults: String(MAXIMO_DE_VIDEOS) }) },
  ...dias.map((dia) => ({ rotulo: 'pais', dia, url: consulta({ startDate: dia, endDate: dia, metrics: metricasDeAudiencia, dimensions: 'country', sort: '-views' }) })),
  ...dias.map((dia) => ({ rotulo: 'audiencia', dia, url: consulta({ startDate: dia, endDate: dia, metrics: 'viewerPercentage', dimensions: 'ageGroup,gender' }) })),
];

const inicio = Date.now();
return requisicoes.map((requisicao) => ({ json: { inicio, versaoApi, fonte, canal, ...requisicao } }));

const etapa1 = $('Montar requisição').all().map((item) => item.json);
const respostas = $input.all().map((item) => item.json);
const contexto = etapa1[0];
const canal = contexto.canal;
const { janela, fonte } = $('Entrada').first().json;
const comDimensoes = fonte?.comDimensoes !== false;
const base = `https://youtubeanalytics.googleapis.com/${contexto.versaoApi}/reports`;
const dataApi = 'https://www.googleapis.com/youtube/v3';

const indiceDoTopo = etapa1.findIndex((requisicao) => requisicao.rotulo === 'top_videos');
const respostaDoTopo = respostas[indiceDoTopo];
const topoOk = respostaDoTopo && !respostaDoTopo.error && respostaDoTopo.statusCode >= 200 && respostaDoTopo.statusCode < 300;
const idsDosVideos = topoOk ? (respostaDoTopo.body?.rows ?? []).map((linha) => String(linha[0])).filter(Boolean) : [];

const consulta = (parametros) => `${base}?${Object.entries({ ids: `channel==${canal}`, ...parametros })
  .map(([chave, valor]) => `${chave}=${encodeURIComponent(valor)}`).join('&')}`;
const metricasDoVideo = 'views,estimatedMinutesWatched,averageViewDuration,likes,comments,shares,subscribersGained,subscribersLost';

const requisicoes = [
  ...idsDosVideos.map((videoId) => ({
    rotulo: 'video_dia',
    videoId,
    url: consulta({ startDate: janela.start, endDate: janela.end, metrics: metricasDoVideo, dimensions: 'day', filters: `video==${videoId}`, sort: 'day' }),
  })),
  ...(comDimensoes && idsDosVideos.length > 0 ? [{
    rotulo: 'videos',
    url: `${dataApi}/videos?part=${encodeURIComponent('snippet,contentDetails,status')}&maxResults=50&id=${encodeURIComponent(idsDosVideos.join(','))}`,
  }] : []),
  ...(comDimensoes ? [{ rotulo: 'playlists', url: `${dataApi}/playlists?part=${encodeURIComponent('snippet,contentDetails,status')}&maxResults=50&channelId=${encodeURIComponent(canal)}` }] : []),
];

return requisicoes.map((requisicao) => ({ json: { ...requisicao } }));

const etapa1 = $('Montar requisição').all().map((item) => item.json);
const respostas1 = $('Chamar API (analytics)').all().map((item) => item.json);
const etapa2 = $('Planejar etapa 2').all().map((item) => item.json);
const respostas2 = $input.all().map((item) => item.json);
const contexto = etapa1[0];
const todas = [
  ...respostas1.map((resposta, indice) => ({ requisicao: etapa1[indice], resposta })),
  ...respostas2.map((resposta, indice) => ({ requisicao: etapa2[indice], resposta })),
];
const requests = todas.length;
const bytes = todas.reduce((total, { resposta }) => total + JSON.stringify(resposta?.body ?? {}).length, 0);

const avisos = [];

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      avisos,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const CONFIGURACAO_DO_PROJETO = /SERVICE_DISABLED|accessNotConfigured|has not been used in project/;
const SINAIS_DE_LIMITE = /RESOURCE_EXHAUSTED|RATE_LIMIT|rateLimitExceeded|userRateLimitExceeded|quotaExceeded|dailyLimitExceeded|Quota exceeded|Exhausted|Too many requests/i;
const SINAIS_DE_COTA_DIARIA = /dailyLimitExceeded|quotaExceeded|per day|PerDay|daily|Number of operations/i;
function falhaDaRecusa(statusCode, erro, detalhe) {
  const texto = JSON.stringify(erro ?? {});
  if (CONFIGURACAO_DO_PROJETO.test(texto)) return { causa: 'api_recusou', detalhe };
  if (statusCode === 429 || SINAIS_DE_LIMITE.test(texto)) {
    return { causa: 'limite_de_uso', detalhe: (SINAIS_DE_COTA_DIARIA.test(texto) ? `cota_diaria: ${detalhe}` : detalhe).slice(0, 500) };
  }
  if (statusCode === 401 || statusCode === 403) return { causa: 'reauth_pending', detalhe };
  return { causa: 'api_recusou', detalhe };
}


const respostaOk = (resposta) => !resposta?.error && resposta?.statusCode >= 200 && resposta?.statusCode < 300;
const essencial = todas.find(({ requisicao }) => requisicao?.rotulo === 'canal_dia');

if (essencial?.resposta?.error) {
  const detalhe = essencial.resposta.error?.message ?? String(essencial.resposta.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

if (essencial && !respostaOk(essencial.resposta)) {
  const recusada = essencial.resposta;
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  return devolver([], [falhaDaRecusa(recusada.statusCode, erro, detalhe)]);
}

const motivoDaRecusa = (resposta) => {
  if (resposta?.error) return `falha de rede: ${resposta.error?.message ?? String(resposta.error)}`;
  const erro = Array.isArray(resposta?.body) ? resposta.body[0]?.error : resposta?.body?.error;
  return String(erro?.message || `HTTP ${resposta?.statusCode}`);
};

function coletaIncompleta(recusas) {
  const porTabela = new Map();
  for (const { tabela, resposta } of recusas) {
    const atual = porTabela.get(tabela) ?? { total: 0, motivo: motivoDaRecusa(resposta) };
    porTabela.set(tabela, { ...atual, total: atual.total + 1 });
  }
  return [...porTabela].map(([tabela, { total, motivo }]) => ({
    causa: 'coleta_incompleta',
    detalhe: `${tabela}: ${total > 1 ? `${total} pedidos recusados, ` : ''}${motivo}`.slice(0, 500),
  }));
}

const lerTabela = (corpo) => {
  const nomes = (corpo?.columnHeaders ?? []).map((coluna) => coluna.name);
  return (corpo?.rows ?? []).map((linha) => Object.fromEntries(nomes.map((nome, indice) => [nome, linha[indice]])));
};

const duracaoEmSegundos = (iso) => {
  const partes = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(String(iso ?? ''));
  if (!partes) return null;
  const [, dias, horas, minutos, segundos] = partes.map((valor) => Number(valor ?? 0));
  return dias * 86400 + horas * 3600 + minutos * 60 + segundos;
};

const linhasDoRecorte = (tabela, coluna) => ({ resposta }) => lerTabela(resposta.body).map((linha) => ({
  _tabela: tabela,
  metricDate: linha.day,
  categoria: linha[coluna],
  views: Number(linha.views ?? 0),
  minutesWatched: Number(linha.estimatedMinutesWatched ?? 0),
}));

const consultaDeReceita = todas.find(({ requisicao }) => requisicao?.rotulo === 'receita');
const receitaOk = Boolean(consultaDeReceita) && respostaOk(consultaDeReceita.resposta);
const receitaSemPermissao = Boolean(consultaDeReceita) && !receitaOk && [401, 403].includes(consultaDeReceita.resposta?.statusCode);
if (receitaSemPermissao) avisos.push({ tipo: 'receita_indisponivel', detalhe: 'canal sem monetização ou sem escopo de receita: estimatedRevenue fica nulo' });
const receitaPorDia = new Map(receitaOk ? lerTabela(consultaDeReceita.resposta.body).map((linha) => [linha.day, Number(linha.estimatedRevenue ?? 0)]) : []);
const receitaDoDia = (linha) => {
  if (receitaPorDia.has(linha.day)) return receitaPorDia.get(linha.day);
  if (linha.estimatedRevenue !== undefined && linha.estimatedRevenue !== null) return Number(linha.estimatedRevenue);
  return receitaOk ? 0 : null;
};

const tradutores = {
  canal_dia: ({ resposta }) => lerTabela(resposta.body).map((linha) => ({
    metricDate: linha.day ?? null,
    views: Number(linha.views ?? 0),
    minutesWatched: Number(linha.estimatedMinutesWatched ?? 0),
    subscribersGained: Number(linha.subscribersGained ?? 0),
    subscribersLost: Number(linha.subscribersLost ?? 0),
    estimatedRevenue: receitaDoDia(linha),
  })),
  receita: () => [],
  origem_trafego: linhasDoRecorte('origem_trafego', 'insightTrafficSourceType'),
  dispositivo: linhasDoRecorte('dispositivo', 'deviceType'),
  local_reproducao: linhasDoRecorte('local_reproducao', 'insightPlaybackLocationType'),
  pais: ({ requisicao, resposta }) => lerTabela(resposta.body).map((linha) => ({
    _tabela: 'pais',
    metricDate: requisicao.dia,
    categoria: linha.country,
    views: Number(linha.views ?? 0),
    minutesWatched: Number(linha.estimatedMinutesWatched ?? 0),
  })),
  audiencia: ({ requisicao, resposta }) => lerTabela(resposta.body).map((linha) => ({
    _tabela: 'audiencia',
    metricDate: requisicao.dia,
    faixaEtaria: linha.ageGroup,
    genero: linha.gender,
    percentualEspectadores: Number(linha.viewerPercentage ?? 0),
  })),
  video_dia: ({ requisicao, resposta }) => lerTabela(resposta.body).map((linha) => ({
    _tabela: 'video_diario',
    videoId: requisicao.videoId,
    metricDate: linha.day,
    views: Number(linha.views ?? 0),
    minutesWatched: Number(linha.estimatedMinutesWatched ?? 0),
    averageViewDuration: Number(linha.averageViewDuration ?? 0),
    likes: Number(linha.likes ?? 0),
    comments: Number(linha.comments ?? 0),
    shares: Number(linha.shares ?? 0),
    subscribersGained: Number(linha.subscribersGained ?? 0),
    subscribersLost: Number(linha.subscribersLost ?? 0),
  })),
  videos: ({ resposta }) => (resposta.body?.items ?? []).map((video) => ({
    _tabela: 'dim_video',
    videoId: video.id,
    titulo: video.snippet?.title ?? null,
    duracaoSegundos: duracaoEmSegundos(video.contentDetails?.duration),
    publicadoEm: video.snippet?.publishedAt ?? null,
    privacidade: video.status?.privacyStatus ?? null,
    categoriaId: video.snippet?.categoryId ?? null,
  })),
  playlists: ({ resposta }) => (resposta.body?.items ?? []).map((playlist) => ({
    _tabela: 'dim_playlist',
    playlistId: playlist.id,
    titulo: playlist.snippet?.title ?? null,
    privacidade: playlist.status?.privacyStatus ?? null,
    qtdVideos: playlist.contentDetails?.itemCount ?? null,
  })),
};

const linhas = todas
  .filter(({ requisicao, resposta }) => requisicao && tradutores[requisicao.rotulo] && respostaOk(resposta))
  .flatMap((entrada) => tradutores[entrada.requisicao.rotulo](entrada));

const TABELA_DO_ROTULO = { 'video_dia': 'video_diario', 'videos': 'dim_video', 'playlists': 'dim_playlist' };

const incompletas = coletaIncompleta(todas
  .filter(({ requisicao, resposta }) => requisicao && tradutores[requisicao.rotulo] && requisicao.rotulo !== 'canal_dia' && !respostaOk(resposta) && !(requisicao.rotulo === 'receita' && receitaSemPermissao))
  .map(({ requisicao, resposta }) => ({ tabela: TABELA_DO_ROTULO[requisicao.rotulo] ?? requisicao.rotulo, resposta })));

if (linhas.length === 0) return devolver([], incompletas.length > 0 ? incompletas : [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi })), incompletas);
